@app.cell(hide_code=True)
def _(mo):
    dropdown = mo.ui.dropdown(
        options=["Expected Improvement", "Log Expected Improvement"],
        value="Log Expected Improvement",
        label="Acquisition Function",
    )
    dropdown
    return (dropdown,)


@app.cell(hide_code=True)
def _(dropdown, load_data):
    data, N_total, N_initial, N_BO = load_data(dropdown.value)
    return N_BO, N_initial, N_total, data


@app.cell(hide_code=True)
def _(N_BO, N_initial, N_total, mo):
    mo.md(f"""
    Loaded data. In total: {N_total} samples, with {N_initial} initial samples and {N_BO} BO iterations
    """)
    return


@app.cell(hide_code=True)
def _(N_BO, mo):
    bo_slider = mo.ui.slider(
        1,
        N_BO,
        full_width=True,
        label="BO Iteration #",
        debounce=False,
        show_value=True,
    )
    bo_slider
    return (bo_slider,)


@app.cell(hide_code=True)
def _(bo_slider, plot_data):
    bo_iteration = bo_slider.value - 1

    plot_data(bo_iteration)
    return


