@app.cell(hide_code=True)
def _(base64, io, np):
    def decode_npz_payload(payload: str) -> dict[str, np.ndarray]:
        """Decode an ASCII payload produced by ``encode_npz_payload``."""
        raw = base64.b85decode(payload.encode("ascii"))
        with np.load(io.BytesIO(raw), allow_pickle=False) as data:
            return {name: data[name] for name in data.files}

    return (decode_npz_payload,)


@app.cell(hide_code=True)
def _(decode_npz_payload, mo):
    @mo.cache
    def load_data(acq_function: str = "Expected Improvement"):

        if acq_function == "Expected Improvement":
            # file = "himmelblau_ei.npz"
            data = decode_npz_payload(get_ei_payload())
        elif acq_function == "Log Expected Improvement":
            # file = "himmelblau.npz"
            data = decode_npz_payload(get_log_ei_payload())
        else:
            raise AssertionError(
                f"Got wrong acquisition function {acq_function}. Should be 'ei' or 'log_ei'"
            )

        # loaded = np.load(file, allow_pickle=False)
        # data = {k: loaded[k] for k in loaded.files}

        N_total = data["sites"].shape[1]
        N_BO = data["acqf_grid_sites"].shape[0]
        N_initial = N_total - N_BO

        return data, N_total, N_initial, N_BO

    return (load_data,)


@app.cell(hide_code=True)
def _(np):
    def limit_colorbar_ticks(colorbar, max_ticks: int = 4) -> None:
        """Limit colorbar labels to a small readable count."""
        vmin, vmax = colorbar.mappable.get_clim()
        if not np.isfinite([vmin, vmax]).all():
            return

        if np.isclose(vmin, vmax):
            ticks = np.asarray([vmin], dtype=float)
        else:
            tick_count = max(3, min(max_ticks, 4))
            ticks = np.linspace(float(vmin), float(vmax), tick_count)

        colorbar.set_ticks(ticks)
        colorbar.minorticks_off()
        colorbar.update_ticks()

    return (limit_colorbar_ticks,)


@app.cell(hide_code=True)
def _(FormatStrFormatter, N_initial, colormaps, limit_colorbar_ticks, np):
    def plot_surrogate_predictions(data, bo_iteration, fig, ax):

        X_surrogate, Y_surrogate = data["grid_sites"][bo_iteration]
        Z_surrogate = data["grid_norm"][bo_iteration]

        surrogate_range = (data["grid_norm"].min(), data["grid_norm"].max())
        surrogate_levels = np.linspace(surrogate_range[0], surrogate_range[1], 50)

        cmap_reversed = colormaps.get_cmap("viridis_r")

        ax.scatter(
            data["sites"][0, : N_initial + bo_iteration + 1][:N_initial],
            data["sites"][1, : N_initial + bo_iteration + 1][:N_initial],
            color="grey",
            marker=".",
            zorder=5,
            label="Initial",
        )
        ax.scatter(
            data["sites"][0, : N_initial + bo_iteration + 1][N_initial:-1],
            data["sites"][1, : N_initial + bo_iteration + 1][N_initial:-1],
            color="black",
            marker="*",
            zorder=10,
            label="BO",
        )
        ax.scatter(
            data["sites"][0, : N_initial + bo_iteration + 1][-1:],
            data["sites"][1, : N_initial + bo_iteration + 1][-1:],
            color="red",
            marker="o",
            zorder=11,
            label="Next",
        )
        ax.set(xlabel="x", ylabel="y", title="Surrogate Predictions")
        cb_pred = ax.contourf(
            X_surrogate,
            Y_surrogate,
            Z_surrogate,
            levels=surrogate_levels,
            cmap=cmap_reversed,
        )
        cbar_pred = fig.colorbar(cb_pred, ax=ax, format=FormatStrFormatter("%.1f"))
        limit_colorbar_ticks(cbar_pred)

    return (plot_surrogate_predictions,)


@app.cell(hide_code=True)
def _(FormatStrFormatter, N_initial, limit_colorbar_ticks, np):
    def plot_acqf(data, bo_iteration, fig, ax):

        X_acqf, Y_acqf = data["acqf_grid_sites"][bo_iteration]
        Z_acqf = data["acqf_grid_predictions"][bo_iteration]

        levels_acqf = np.linspace(Z_acqf.min(), Z_acqf.max(), 20)

        cb_acqf = ax.contourf(X_acqf, Y_acqf, Z_acqf, levels=levels_acqf)
        cbar_acqf = fig.colorbar(
            cb_acqf, ax=ax, format=FormatStrFormatter("%6.2f")
        )
        limit_colorbar_ticks(cbar_acqf)

        ax.scatter(
            data["sites"][0, : N_initial + bo_iteration + 1][:N_initial],
            data["sites"][1, : N_initial + bo_iteration + 1][:N_initial],
            color="grey",
            marker=".",
            zorder=5,
        )
        ax.scatter(
            data["sites"][0, : N_initial + bo_iteration + 1][N_initial:-1],
            data["sites"][1, : N_initial + bo_iteration + 1][N_initial:-1],
            color="black",
            marker="*",
            zorder=10,
        )
        ax.scatter(
            data["sites"][0, : N_initial + bo_iteration + 1][-1:],
            data["sites"][1, : N_initial + bo_iteration + 1][-1:],
            color="red",
            marker="o",
            zorder=11,
        )
        ax.set(xlabel="x", ylabel="y", title="Acquisition Function")
        # ax.yaxis.set_major_formatter(FormatStrFormatter("%6.2f"))
    return (plot_acqf,)


@app.cell(hide_code=True)
def _(FormatStrFormatter, MaxNLocator, N_initial, data, np):
    min_values_norm = np.minimum.accumulate(data["values_norm"])


    def plot_minimum_over_time(data, bo_iteration: int, ax) -> None:

        min_values_bo_iteration = min_values_norm[: N_initial + bo_iteration]
        best_value = min_values_bo_iteration[-1]
        best_index = np.argmin(min_values_bo_iteration) - N_initial + 1 + 1
        iteration_indices = np.arange(bo_iteration + 1) + 1

        ax.step(
            iteration_indices,
            min_values_norm[N_initial - 1 : N_initial + bo_iteration],
            where="post",
            color="C0",
            linewidth=2,
        )
        ax.set(
            xlabel="BO Iteration",
            ylabel="Best Value",
            title=f"Learning Curve (minimum {best_value:6.3f} at iteration {best_index})",
        )
        ax.xaxis.set_major_locator(MaxNLocator(integer=True))
        ax.yaxis.set_major_formatter(FormatStrFormatter("%.2f"))

    return (plot_minimum_over_time,)


@app.cell(hide_code=True)
def _(io, mo):
    def convert_fig_to_html(fig):
        f = io.StringIO()
        fig.savefig(f, format="svg", bbox_inches="tight", dpi=300)
        svg_str = f.getvalue()
        return mo.Html(svg_str)

    return (convert_fig_to_html,)


@app.cell(hide_code=True)
def _(
    Figure,
    GridSpec,
    convert_fig_to_html,
    data,
    mo,
    plot_acqf,
    plot_minimum_over_time,
    plot_surrogate_predictions,
):
    @mo.cache
    def plot_data(bo_iteration: int):

        fig = Figure(figsize=(14, 6), dpi=300)

        gs = GridSpec(2, 2, figure=fig, hspace=0.8, wspace=0.3)
        axes = [
            fig.add_subplot(gs[0, 0]),
            fig.add_subplot(gs[0, 1]),
            fig.add_subplot(gs[1, :]),
        ]

        plot_surrogate_predictions(data, bo_iteration, fig, axes[0])
        plot_acqf(data, bo_iteration, fig, axes[1])
        plot_minimum_over_time(data, bo_iteration, axes[2])

        # collect labels only from upper-left subplot
        handles, labels = axes[0].get_legend_handles_labels()
        fig.legend(
            handles,
            labels,
            loc="upper center",
            bbox_to_anchor=(0.5, 0.55),  # adjust y as needed
            ncol=3,
            frameon=True,
        )

        fig.suptitle(f"BO Iteration: {bo_iteration + 1}")

        html = convert_fig_to_html(fig)
        return html

    return (plot_data,)


@app.cell(hide_code=True)
def _(N_BO, plot_data):
    is_initial_run = True
    if is_initial_run:
        for i in range(1, N_BO):
            plot_data(i)
        is_initial_run = False
    return


@app.cell
def _():
    return


if __name__ == "__main__":
    app.run()
